resource "cloudflare_rate_limit" "example" {
  zone_id = "${var.zone_id}"
  description = "Limit abusive endpoint during L7 flood"
  match {
    request {
      methods = ["GET", "POST"]
      schemes = ["HTTP", "HTTPS"]
      url = "example.com/login*"
    }
  }
  threshold = 1000
  period = 10
  action {
    mode = "challenge"
    timeout = 60
  }
}

