## Compact cache‑aside example (Python-ish pseudocode)

```python
def get_product(id):
    key = f'product:{id}'
    value = cache.get(key)
    if value:
        return deserialize(value)

    row = db.fetch('SELECT * FROM products WHERE id=%s', id)
    if row:
        cache.set(key, serialize(row), ex=300)  # 5m TTL
    return row

def update_product(id, payload):
    db.update('UPDATE products SET ... WHERE id=%s', id)
    cache.delete(f'product:{id}')  # invalidate so next read reloads
```
